import { z } from 'zod';

import { PROGRESS_TEXT_MAX_CHARS, RESULT_MAX_BYTES } from './constants.js';
import { leaseSchema, taskIdSchema, taskSchema } from './task.js';
import { semverSchema } from './version.js';

/** Worker session identifier, generated by the skill/CLI when the session starts. */
export const workerIdSchema = z.string().min(1).max(128);
export type WorkerId = z.infer<typeof workerIdSchema>;

/**
 * Shared part of all worker requests. Versions go in every call: the CLI keeps no state
 * between runs, the handshake (rpc-design §9) happens on every request and costs little.
 * Every such request is a heartbeat (rpc-design §7).
 */
const workerRequestBase = z.object({
    protocolVersion: semverSchema,
    cliVersion: semverSchema,
    workerId: workerIdSchema,
});

/**
 * `sherpa worker register` registers the session as the PR worker at skill startup (rpc-design §7).
 * Reconnection is a new registration with a new workerId. The old worker's leases expire on their own.
 * While the previous worker is alive, a second is rejected with `worker_conflict` (spec §3.7).
 */
export const workerRegisterRequestSchema = workerRequestBase.extend({
    /** Harness label for UI status ("claude-code", "codex"), a free-form string. */
    harness: z.string().min(1).max(64).optional(),
});
export type WorkerRegisterRequest = z.infer<typeof workerRegisterRequestSchema>;

export const workerRegisterResponseSchema = z.object({
    kind: z.literal('registered'),
    message: z.string(),
});
export type WorkerRegisterResponse = z.infer<typeof workerRegisterResponseSchema>;

/**
 * PR worker state as seen by the server (rpc-design §7), displayed in the UI.
 * `disconnected` means more than `WORKER_DEAD_AFTER_SECONDS` have passed since the last CLI call.
 */
export const workerStatusSchema = z.discriminatedUnion('kind', [
    /** No worker has ever registered for this PR. */
    z.object({ kind: z.literal('never') }),
    z.object({
        kind: z.literal('connected'),
        workerId: workerIdSchema,
        harness: z.string().optional(),
        registeredAt: z.iso.datetime(),
        lastSeenAt: z.iso.datetime(),
    }),
    z.object({
        kind: z.literal('disconnected'),
        workerId: workerIdSchema,
        harness: z.string().optional(),
        registeredAt: z.iso.datetime(),
        lastSeenAt: z.iso.datetime(),
    }),
]);
export type WorkerStatus = z.infer<typeof workerStatusSchema>;

/** `sherpa worker next` long-polls for the next task. */
export const workerNextRequestSchema = workerRequestBase;
export type WorkerNextRequest = z.infer<typeof workerNextRequestSchema>;

export const workerNextResponseSchema = z.discriminatedUnion('kind', [
    /** The task is leased. While the lease is live, another `next` returns the same task. */
    z.object({ kind: z.literal('task'), task: taskSchema, lease: leaseSchema }),
    /** No tasks, the long poll timed out. Call `next` again. */
    z.object({ kind: z.literal('idle'), message: z.string() }),
    /** Worker work is finished (DONE), the session can exit. */
    z.object({ kind: z.literal('done'), message: z.string() }),
]);
export type WorkerNextResponse = z.infer<typeof workerNextResponseSchema>;

/** `sherpa task complete <id> --file <path>`: the CLI sends the result file contents. */
export const taskCompleteRequestSchema = workerRequestBase.extend({
    taskId: taskIdSchema,
    result: z.string().refine(
        (value) => new TextEncoder().encode(value).byteLength <= RESULT_MAX_BYTES,
        { message: `result exceeds ${String(RESULT_MAX_BYTES)} bytes, the task will fail` },
    ),
});
export type TaskCompleteRequest = z.infer<typeof taskCompleteRequestSchema>;

export const taskCompleteResponseSchema = z.discriminatedUnion('kind', [
    z.object({ kind: z.literal('accepted'), message: z.string() }),
    /** Fail-closed result validation failed. Errors are listed in prompt format. Fix them and call again. */
    z.object({ kind: z.literal('rejected'), errors: z.array(z.string()).min(1) }),
    /** Task already closed, repeated call is a no-op (rpc-design §5, idempotency). */
    z.object({ kind: z.literal('noop'), message: z.string() }),
]);
export type TaskCompleteResponse = z.infer<typeof taskCompleteResponseSchema>;

/** `sherpa task progress <id> --text`: a cheap status signal, shown as "agent working: …" in the UI. */
export const taskProgressRequestSchema = workerRequestBase.extend({
    taskId: taskIdSchema,
    text: z.string().min(1).max(PROGRESS_TEXT_MAX_CHARS),
});
export type TaskProgressRequest = z.infer<typeof taskProgressRequestSchema>;

/** `sherpa task fail <id> --reason`: explicit failure. The task fails with a reason visible in the UI. */
export const taskFailRequestSchema = workerRequestBase.extend({
    taskId: taskIdSchema,
    reason: z.string().min(1),
});
export type TaskFailRequest = z.infer<typeof taskFailRequestSchema>;

/** Shared progress/fail response: accepted, or a no-op if the task is already closed. */
export const taskAckResponseSchema = z.discriminatedUnion('kind', [
    z.object({ kind: z.literal('accepted') }),
    z.object({ kind: z.literal('noop'), message: z.string() }),
]);
export type TaskAckResponse = z.infer<typeof taskAckResponseSchema>;

/**
 * RPC error codes. Error text is human-readable: both the model in CLI output
 * and the reviewer in the UI can read it (rpc-design §9).
 */
export const rpcErrorCodeSchema = z.enum([
    /** Missing or invalid bearer token. */
    'unauthorized',
    /** Incompatible protocol versions: "update the skill/server". */
    'version_incompatible',
    /** The request failed schema validation. */
    'bad_request',
    /** No task with this id. */
    'unknown_task',
    /** The task is not leased to this worker. */
    'lease_not_held',
    /** A live worker already exists for the PR, a second one is rejected (spec §3.7). */
    'worker_conflict',
    /** The `complete` result exceeded the limit, the task failed (spec §3.5). */
    'result_too_large',
    /** Internal server error. The caller is not at fault, a retry may help. */
    'internal',
]);
export type RpcErrorCode = z.infer<typeof rpcErrorCodeSchema>;

export const rpcErrorSchema = z.object({
    error: z.object({
        code: rpcErrorCodeSchema,
        message: z.string().min(1),
        /** Details as a list, for example field validation errors. */
        details: z.array(z.string()).optional(),
    }),
});
export type RpcError = z.infer<typeof rpcErrorSchema>;
